param(
    [string]$Root = (Get-Location).Path,
    [switch]$SkipInstall,
    [switch]$SkipFormat,
    [switch]$SkipBuild
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

function Ensure-Directory {
    param([Parameter(Mandatory = $true)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) {
        New-Item -ItemType Directory -Path $Path -Force | Out-Null
    }
}

function Write-Utf8File {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath,
        [Parameter(Mandatory = $true)][string]$Base64Content
    )

    $target = Join-Path $Root $RelativePath
    Ensure-Directory (Split-Path -Parent $target)
    $bytes = [Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($target, $bytes)
    Write-Host "[PATCH] $RelativePath"
}

$Root = [System.IO.Path]::GetFullPath($Root)

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
    throw "package.json was not found in '$Root'. Run this script from the backend root or pass -Root."
}
if (-not (Test-Path -LiteralPath (Join-Path $Root "src"))) {
    throw "src folder was not found in '$Root'."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $Root ".codegen-backup\swagger-build-fix-$timestamp"
Ensure-Directory $backupRoot

Write-Host ""
Write-Host "La Favola build-error + Swagger patch"
Write-Host "Backend: $Root"
Write-Host "Backup:  $backupRoot"
Write-Host ""

# Full safety backup of source/config metadata touched by this patch.
Copy-Item -LiteralPath (Join-Path $Root "src") -Destination (Join-Path $backupRoot "src") -Recurse -Force
Copy-Item -LiteralPath (Join-Path $Root "package.json") -Destination (Join-Path $backupRoot "package.json") -Force
if (Test-Path -LiteralPath (Join-Path $Root "package-lock.json")) {
    Copy-Item -LiteralPath (Join-Path $Root "package-lock.json") -Destination (Join-Path $backupRoot "package-lock.json") -Force
}
if (Test-Path -LiteralPath (Join-Path $Root "nest-cli.json")) {
    Copy-Item -LiteralPath (Join-Path $Root "nest-cli.json") -Destination (Join-Path $backupRoot "nest-cli.json") -Force
}

Write-Host "[BACKUP] Existing source and package configuration saved."

Write-Utf8File -RelativePath 'src\common\repositories\base.repository.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\audit\interfaces\audit-context.interface.ts' -Base64Content 'ZXhwb3J0IGludGVyZmFjZSBBdWRpdENvbnRleHQgewogIGFjdG9yVXNlcklkPzogc3RyaW5nOwogIHJlc3RhdXJhbnRJZD86IHN0cmluZzsKICBjb3JyZWxhdGlvbklkPzogc3RyaW5nOwogIGlwQWRkcmVzcz86IHN0cmluZzsKICB1c2VyQWdlbnQ/OiBzdHJpbmc7CiAgbWV0YWRhdGE/OiBSZWNvcmQ8c3RyaW5nLCB1bmtub3duPjsKfQo='

Write-Utf8File -RelativePath 'src\modules\pricing\interfaces\price-breakdown.interface.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\pricing\pricing.service.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\carts\carts.service.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\checkout\dto\checkout.dto.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\checkout\checkout.service.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\coupons\coupons.service.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\promotions\promotions.service.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\deliveries\dto\update-location.dto.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\deliveries\deliveries.service.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\media\dto\create-upload-url.dto.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\media\media.service.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\orders\orders.service.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\payments\payments.service.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\pizza-builder\pizza-builder.service.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\restaurants\restaurants.service.ts' -Base64Content ''

Write-Utf8File -RelativePath 'src\modules\auth\auth.controller.ts' -Base64Content ''

# ---------------------------------------------------------------------------
# Swagger dependency/config compatibility
# ---------------------------------------------------------------------------
$packagePatch = @'
const fs = require('fs');
const path = require('path');
const root = process.argv[2];
const packagePath = path.join(root, 'package.json');
const pkg = JSON.parse(fs.readFileSync(packagePath, 'utf8'));
pkg.dependencies = pkg.dependencies || {};

// NestJS 10-compatible Swagger major. This also resolves the Nest 10 vs Swagger 11 peer conflict.
pkg.dependencies['@nestjs/swagger'] = '^7.4.2';
pkg.dependencies['dotenv'] = pkg.dependencies['dotenv'] || '^16.4.7';

fs.writeFileSync(packagePath, JSON.stringify(pkg, null, 2) + '\n');

const nestPath = path.join(root, 'nest-cli.json');
if (fs.existsSync(nestPath)) {
  const nest = JSON.parse(fs.readFileSync(nestPath, 'utf8'));
  nest.compilerOptions = nest.compilerOptions || {};
  const plugins = Array.isArray(nest.compilerOptions.plugins)
    ? nest.compilerOptions.plugins
    : [];

  const filtered = plugins.filter((plugin) => {
    if (typeof plugin === 'string') return plugin !== '@nestjs/swagger/plugin';
    return plugin?.name !== '@nestjs/swagger/plugin';
  });

  filtered.push({
    name: '@nestjs/swagger/plugin',
    options: {
      classValidatorShim: true,
      introspectComments: true
    }
  });

  nest.compilerOptions.plugins = filtered;
  fs.writeFileSync(nestPath, JSON.stringify(nest, null, 2) + '\n');
}

const mainPath = path.join(root, 'src', 'main.ts');
if (fs.existsSync(mainPath)) {
  let main = fs.readFileSync(mainPath, 'utf8');
  main = main
    .replace(/\.setTitle\([^)]*\)/, ".setTitle('La Favola Pizza Restaurant API')")
    .replace(
      /\.setDescription\([^)]*\)/,
      ".setDescription('Customer ordering, pizza customization, checkout, payments, delivery tracking, promotions, support, and restaurant administration API')"
    );
  fs.writeFileSync(mainPath, main);
}
'@

$packagePatchPath = Join-Path $env:TEMP "la-favola-package-patch-$timestamp.js"
Set-Content -LiteralPath $packagePatchPath -Value $packagePatch -Encoding UTF8
& node $packagePatchPath $Root
if ($LASTEXITCODE -ne 0) {
    throw "Failed to update package.json / nest-cli.json."
}
Remove-Item -LiteralPath $packagePatchPath -Force -ErrorAction SilentlyContinue
Write-Host "[CONFIG] NestJS Swagger plugin and compatible Swagger dependency configured."

# Swagger mapped types must come from @nestjs/swagger so inherited DTO fields are documented.
Get-ChildItem -LiteralPath (Join-Path $Root "src") -Filter "*.dto.ts" -Recurse | ForEach-Object {
    $content = Get-Content -LiteralPath $_.FullName -Raw
    $updated = $content.Replace("@nestjs/mapped-types", "@nestjs/swagger")
    if ($updated -ne $content) {
        Set-Content -LiteralPath $_.FullName -Value $updated -Encoding UTF8
        Write-Host "[SWAGGER DTO] $($_.FullName.Substring($Root.Length + 1))"
    }
}

# ---------------------------------------------------------------------------
# Add Swagger docs to every controller route.
# - ApiTags on every controller
# - ApiOperation on every HTTP route
# - ApiBody on every DTO/body route
# - ApiParam for path params
# - ApiQuery for named query params
# - success/error ApiResponse entries
# Existing custom decorators are preserved.
# ---------------------------------------------------------------------------
$swaggerHelperBytes = [Convert]::FromBase64String('')
$swaggerHelperPath = Join-Path $env:TEMP "la-favola-swaggerify-$timestamp.js"
[System.IO.File]::WriteAllBytes($swaggerHelperPath, $swaggerHelperBytes)

& node $swaggerHelperPath $Root
if ($LASTEXITCODE -ne 0) {
    throw "Swagger controller annotation step failed."
}
Remove-Item -LiteralPath $swaggerHelperPath -Force -ErrorAction SilentlyContinue

# ---------------------------------------------------------------------------
# Install / verify
# ---------------------------------------------------------------------------
Push-Location $Root
try {
    if (-not $SkipInstall) {
        Write-Host ""
        Write-Host "[NPM] Installing compatible dependencies..."
        npm install
        if ($LASTEXITCODE -ne 0) {
            throw "npm install failed. Your original files are preserved in $backupRoot"
        }
    }

    if (-not $SkipFormat) {
        Write-Host ""
        Write-Host "[FORMAT] Running formatter..."
        npm run format
        if ($LASTEXITCODE -ne 0) {
            throw "Formatting failed."
        }
    }

    if (-not $SkipBuild) {
        Write-Host ""
        Write-Host "[BUILD] Compiling NestJS backend..."
        npm run build
        if ($LASTEXITCODE -ne 0) {
            throw "Build still has errors. Copy the complete new build output and send it back. Backup: $backupRoot"
        }
    }
}
finally {
    Pop-Location
}

Write-Host ""
Write-Host "============================================================"
Write-Host "PATCH COMPLETE"
Write-Host "============================================================"
Write-Host "Fixed the reported DTO/entity/service type mismatches."
Write-Host "Swagger documentation was added across all controller routes."
Write-Host "Request bodies are explicitly documented for @Body() routes."
Write-Host "Named path/query parameters are documented."
Write-Host "Swagger DTO plugin is enabled with class-validator metadata."
Write-Host "Swagger UI remains available at /api/docs."
Write-Host "Backup: $backupRoot"
Write-Host "============================================================"
